// Build a rich HTML digest of the posts published within the look-back window.
const config = $('Set Email and Post Limits').first().json;
const posts = $input.all().map(item => item.json);

// No new posts since last run → stop silently, no email is sent.
if (!posts || posts.length === 0) {
  return [];
}

const rows = posts.map((post, i) => {
  const title = post.title?.rendered || post.title || 'Untitled';
  const link = post.link || '#';
  const date = (post.date_gmt || post.date || '').slice(0, 10);
  const excerpt = (post.excerpt?.rendered || '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&[a-z]+;/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 220);
  const image = post._embedded?.['wp:featuredmedia']?.[0]?.source_url || '';
  const imgBlock = image
    ? `<tr><td style="padding:0 0 14px 0;"><img src="${image}" alt="${title}" style="width:100%;max-width:512px;height:auto;border-radius:6px;display:block;" /></td></tr>`
    : '';
  return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:0 0 24px 0;">
    ${imgBlock}
    <tr><td style="font-family:Arial,Helvetica,sans-serif;font-size:12px;color:#8a94a6;padding:0 0 6px 0;">${date} &middot; Post ${i + 1} of ${posts.length}</td></tr>
    <tr><td style="font-family:Arial,Helvetica,sans-serif;font-size:16px;font-weight:bold;color:#0d2b5b;padding:0 0 8px 0;"><a href="${link}" style="color:#0d2b5b;text-decoration:none;">${title}</a></td></tr>
    <tr><td style="font-family:Arial,Helvetica,sans-serif;font-size:14px;color:#4a5568;line-height:1.6;padding:0 0 14px 0;">${excerpt}</td></tr>
    <tr><td><a href="${link}" style="display:inline-block;background:#0d2b5b;color:#ffffff;font-family:Arial,Helvetica,sans-serif;font-size:13px;font-weight:bold;text-decoration:none;padding:9px 20px;border-radius:4px;">Read more &rarr;</a></td></tr>
  </table>`;
}).join('');

const siteUrl = config.siteUrl;
const html = `<div style="background:#f4f6f8;padding:24px;font-family:Arial,Helvetica,sans-serif;">
  <div style="max-width:560px;margin:0 auto;background:#ffffff;border-radius:8px;overflow:hidden;border:1px solid #e3e8ee;">
    <div style="background:#0d2b5b;padding:16px 24px;"><span style="color:#ffffff;font-size:18px;font-weight:bold;">&#128232; New posts from ${siteUrl}</span></div>
    <div style="padding:24px;">${rows}</div>
    <div style="padding:12px 24px;border-top:1px solid #eef1f5;color:#8a94a6;font-size:12px;">Auto-generated daily by n8n &middot; WordPress REST API, no plugin needed.</div>
  </div>
</div>`;

const text = posts.map((p, i) => {
  const t = p.title?.rendered || p.title || 'Untitled';
  const l = p.link || '';
  const d = (p.date_gmt || p.date || '').slice(0, 10);
  return `${i + 1}. ${t} (${d})\n${l}`;
}).join('\n\n');

return [{
  json: {
    html,
    text: `New posts on ${siteUrl}:\n\n${text}`,
    postCount: posts.length,
    siteUrl,
  },
}];

// No new posts in the look-back window → nothing to send.
// Returning an empty array stops this branch cleanly.
return [];
